sys_script.script:
(function executeRule(current, previous) {

    var TARGET_TABLE =
        'x_1549902_asean_0_learning_application';

    /*
     * Run only when an approval is changed to Cancelled.
     */
    if (!current.state.changesTo('cancelled')) {
        return;
    }

    /*
     * Task-based approvals use the sysapproval field.
     */
    if (current.sysapproval.nil()) {
        return;
    }

    var parentRecord = current.sysapproval.getRefRecord();

    if (!parentRecord || !parentRecord.isValidRecord()) {
        return;
    }

    /*
     * Ensure the approval belongs specifically to the
     * Learning Application table.
     */
    if (parentRecord.getTableName() !== TARGET_TABLE) {
        return;
    }

    /*
     * Change only the remaining requested approvals
     * for the same Learning Application record.
     */
    var approvalGR = new GlideRecord('sysapproval_approver');
    approvalGR.addQuery('sysapproval', current.sysapproval);
    approvalGR.addQuery('state', 'requested');
    approvalGR.addQuery('sys_id', '!=', current.getUniqueValue());

    /*
     * Restrict the update to the same approval group.
     */
    if (!current.group.nil()) {
        approvalGR.addQuery('group', current.group);
    }

    approvalGR.query();

    while (approvalGR.next()) {
        approvalGR.setValue('state', 'not_required');
        approvalGR.update();
    }

})(current, previous);
